function [tau] = gravity_gradient_torque(rm, r, j, mu)
%GRAVITY_GRADIENT_TORQUE  The gravity-gradient torque [N m], body axes, at the inertial position r, rm the inertial-to-body matrix, j the
%   inertia (body axes) and mu the Earth's gravitational parameter.
%   rm: real[1][3][3] (passed a plain number)
%   r: real[m][3] (passed in m)
%   j: real[kg m^2][3][3] (passed in m^2 kg)
%   mu: real[m^3/s^2] (passed in m^3/s^2)
%   returns tau: real[N m][3] (passed in m^2 kg/s^2)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    tau = zeros(3, 1);
    rb = asils.pc.mv(rm, r);
    rn = asils.pc.norm_(rb);
    tau = (asils.pc.cross_(rb, asils.pc.mv(j, rb)) * ((3 * mu) / asils.pc.ipow(rn, 5)));
end
